import unittest

from report import daily_revenue


class Regression(unittest.TestCase):
    def test_a_refund_reduces_the_day(self):
        orders = [
            {"ts": 1772433000, "amount_cents": 1000, "kind": "sale"},
            {"ts": 1772433000, "amount_cents": 300, "kind": "refund"},
        ]
        self.assertEqual(daily_revenue(orders, 330), {"2026-03-02": 700})

    def test_a_store_behind_utc(self):
        # 03:00 UTC on 2 March is 22:00 on 1 March in New York.
        orders = [{"ts": 1772420400, "amount_cents": 250, "kind": "sale"}]
        self.assertEqual(daily_revenue(orders, -300), {"2026-03-01": 250})

    def test_sales_on_one_day_add_up(self):
        orders = [{"ts": 1772433000, "amount_cents": 100, "kind": "sale"}] * 3
        self.assertEqual(daily_revenue(orders, 330), {"2026-03-02": 300})
